Create:
nano src/config/security.config.js
Paste:
'use strict';/** * STEP 28 — API Security Configuration */const parseOrigins = (value) => {  if (!value) return [];  return value    .split(',')    .map((origin) => origin.trim())    .filter(Boolean);};const securityConfig = {  requestBodyLimit: process.env.REQUEST_BODY_LIMIT || '1mb',  cors: {    allowedOrigins: parseOrigins(process.env.CORS_ALLOWED_ORIGINS),    allowedMethods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],    allowedHeaders: [      'Content-Type',      'Authorization',      'x-api-key',      'x-request-id',      'x-service-name'    ],    exposedHeaders: ['x-request-id'],    credentials: true  },  rateLimit: {    windowMs: Number(process.env.RATE_LIMIT_WINDOW_MS || 15 * 60 * 1000),    maxRequests: Number(process.env.RATE_LIMIT_MAX_REQUESTS || 100)  },  authRateLimit: {    windowMs: Number(process.env.AUTH_RATE_LIMIT_WINDOW_MS || 15 * 60 * 1000),    maxRequests: Number(process.env.AUTH_RATE_LIMIT_MAX_REQUESTS || 10)  },  apiKey: {    enabled: String(process.env.ENABLE_API_KEY_PROTECTION || 'true') === 'true',    internalApiKey: process.env.INTERNAL_API_KEY || null  },  logging: {    enableSuspiciousLogging:      String(process.env.ENABLE_SUSPICIOUS_REQUEST_LOGGING || 'true') === 'true'  }};module.exports = securityConfig;

4. Create Environment Secret Validator
Create:
nano src/config/env.validator.js
Paste:
'use strict';/** * STEP 28 — Environment Secret Protection * * This file validates required secrets at startup. * It prevents the API from starting with unsafe or missing secrets. */const REQUIRED_ENV_VARS = [  'JWT_SECRET',  'INTERNAL_API_KEY'];const weakSecretValues = [  'secret',  'password',  'admin',  'changeme',  'change_me',  'default',  'test',  '123456',  'CHANGE_THIS_TO_A_LONG_RANDOM_SECRET_VALUE'];function validateEnvironmentSecrets() {  const errors = [];  REQUIRED_ENV_VARS.forEach((key) => {    const value = process.env[key];    if (!value) {      errors.push(`${key} is missing`);      return;    }    if (value.length < 32) {      errors.push(`${key} must be at least 32 characters`);    }    if (weakSecretValues.includes(value.trim())) {      errors.push(`${key} contains a weak/default value`);    }  });  if (errors.length > 0) {    console.error('Security environment validation failed:');    errors.forEach((error) => console.error(`- ${error}`));    if (process.env.NODE_ENV === 'production') {      process.exit(1);    }    console.warn(      'WARNING: Running with insecure environment values because NODE_ENV is not production.'    );  }}module.exports = {  validateEnvironmentSecrets};

5. Create Suspicious Request Logger
Create:
nano src/middleware/suspiciousRequest.middleware.js
Paste:
'use strict';/** * STEP 28 — Suspicious Request Logging Middleware */const crypto = require('crypto');const securityConfig = require('../config/security.config');const suspiciousPatterns = [  /(\bUNION\b|\bSELECT\b|\bINSERT\b|\bUPDATE\b|\bDELETE\b|\bDROP\b|\bALTER\b|\bTRUNCATE\b)/i,  /('|")\s*OR\s*('|")?\d+('|")?\s*=\s*('|")?\d+/i,  /--|\/\*|\*\//,  /<script\b[^>]*>/i,  /javascript:/i,  /\.\.\//,  /etc\/passwd/i,  /cmd\.exe/i,  /powershell/i,  /wget\s+/i,  /curl\s+/i];function safeStringify(value) {  try {    return JSON.stringify(value);  } catch {    return String(value);  }}function containsSuspiciousContent(value) {  if (value === null || value === undefined) return false;  const text =    typeof value === 'string'      ? value      : safeStringify(value);  return suspiciousPatterns.some((pattern) => pattern.test(text));}function maskSensitiveHeaders(headers = {}) {  const masked = { ...headers };  const sensitiveHeaderNames = [    'authorization',    'x-api-key',    'cookie',    'set-cookie'  ];  sensitiveHeaderNames.forEach((headerName) => {    if (masked[headerName]) {      masked[headerName] = '[MASKED]';    }  });  return masked;}function suspiciousRequestLogger(req, res, next) {  if (!securityConfig.logging.enableSuspiciousLogging) {    return next();  }  const checks = {    url: req.originalUrl,    query: req.query,    body: req.body,    params: req.params,    userAgent: req.headers['user-agent']  };  const detectedFields = Object.entries(checks)    .filter(([, value]) => containsSuspiciousContent(value))    .map(([key]) => key);  if (detectedFields.length > 0) {    const incidentId = crypto.randomBytes(8).toString('hex');    console.warn(      JSON.stringify({        level: 'warn',        event: 'SUSPICIOUS_REQUEST_DETECTED',        incidentId,        requestId: req.headers['x-request-id'] || null,        method: req.method,        path: req.originalUrl,        ip: req.ip,        detectedFields,        headers: maskSensitiveHeaders(req.headers),        timestamp: new Date().toISOString()      })    );  }  return next();}module.exports = suspiciousRequestLogger;

6. Create SQL Injection Protection Middleware
Create:
nano src/middleware/sqlInjectionProtection.middleware.js
Paste:
'use strict';/** * STEP 28 — SQL Injection Protection Middleware * * Important: * This middleware is a defensive layer only. * The main protection must remain parameterized SQL queries. */const sqlInjectionPatterns = [  /(\bUNION\b\s+\bSELECT\b)/i,  /(\bSELECT\b.+\bFROM\b)/i,  /(\bINSERT\b\s+\bINTO\b)/i,  /(\bUPDATE\b.+\bSET\b)/i,  /(\bDELETE\b\s+\bFROM\b)/i,  /(\bDROP\b\s+\bTABLE\b)/i,  /(\bALTER\b\s+\bTABLE\b)/i,  /(\bTRUNCATE\b\s+\bTABLE\b)/i,  /('|")\s*OR\s*('|")?\d+('|")?\s*=\s*('|")?\d+/i,  /('|")\s*OR\s*('|")?[a-zA-Z0-9_]+('|")?\s*=\s*('|")?[a-zA-Z0-9_]+/i,  /--/,  /\/\*/,  /\*\//,  /;\s*(DROP|DELETE|UPDATE|INSERT|ALTER|TRUNCATE)\b/i];function stringifyValue(value) {  if (value === null || value === undefined) return '';  if (typeof value === 'string') return value;  try {    return JSON.stringify(value);  } catch {    return String(value);  }}function hasSqlInjection(value) {  const text = stringifyValue(value);  return sqlInjectionPatterns.some((pattern) => pattern.test(text));}function scanObject(obj) {  if (!obj || typeof obj !== 'object') {    return false;  }  return Object.values(obj).some((value) => {    if (value && typeof value === 'object') {      return scanObject(value);    }    return hasSqlInjection(value);  });}function sqlInjectionProtection(req, res, next) {  const suspicious =    hasSqlInjection(req.originalUrl) ||    scanObject(req.query) ||    scanObject(req.params) ||    scanObject(req.body);  if (!suspicious) {    return next();  }  console.warn(    JSON.stringify({      level: 'warn',      event: 'SQL_INJECTION_ATTEMPT_BLOCKED',      requestId: req.headers['x-request-id'] || null,      method: req.method,      path: req.originalUrl,      ip: req.ip,      timestamp: new Date().toISOString()    })  );  return res.status(400).json({    success: false,    message: 'Invalid request payload',    errorCode: 'INVALID_REQUEST_SECURITY_CHECK',    requestId: req.headers['x-request-id'] || null  });}module.exports = sqlInjectionProtection;

7. Create API Key Protection Middleware
Create:
nano src/middleware/apiKey.middleware.js
Paste:
'use strict';/** * STEP 28 — API Key Protection Middleware * * Used for internal service-to-service endpoints. */const crypto = require('crypto');const securityConfig = require('../config/security.config');function safeCompare(valueA, valueB) {  if (!valueA || !valueB) return false;  const bufferA = Buffer.from(valueA);  const bufferB = Buffer.from(valueB);  if (bufferA.length !== bufferB.length) return false;  return crypto.timingSafeEqual(bufferA, bufferB);}function apiKeyProtection(req, res, next) {  if (!securityConfig.apiKey.enabled) {    return next();  }  const configuredApiKey = securityConfig.apiKey.internalApiKey;  const providedApiKey = req.headers['x-api-key'];  if (!configuredApiKey) {    return res.status(500).json({      success: false,      message: 'API key protection is enabled but INTERNAL_API_KEY is not configured',      errorCode: 'API_KEY_NOT_CONFIGURED',      requestId: req.headers['x-request-id'] || null    });  }  if (!providedApiKey || !safeCompare(providedApiKey, configuredApiKey)) {    console.warn(      JSON.stringify({        level: 'warn',        event: 'INVALID_OR_MISSING_API_KEY',        requestId: req.headers['x-request-id'] || null,        method: req.method,        path: req.originalUrl,        ip: req.ip,        timestamp: new Date().toISOString()      })    );    return res.status(401).json({      success: false,      message: 'Unauthorized service request',      errorCode: 'INVALID_API_KEY',      requestId: req.headers['x-request-id'] || null    });  }  return next();}module.exports = apiKeyProtection;

