10. Create Security Middleware Aggregator
Create:
nano src/middleware/security.middleware.js
Paste:
'use strict';/** * STEP 28 — Central API Security Middleware */const helmet = require('helmet');const cors = require('cors');const hpp = require('hpp');const securityConfig = require('../config/security.config');const suspiciousRequestLogger = require('./suspiciousRequest.middleware');const sqlInjectionProtection = require('./sqlInjectionProtection.middleware');const { standardRateLimiter } = require('./rateLimit.middleware');function corsOptionsDelegate(req, callback) {  const requestOrigin = req.header('Origin');  const allowedOrigins = securityConfig.cors.allowedOrigins;  /**   * Allow server-to-server and curl requests with no Origin header.   */  if (!requestOrigin) {    return callback(null, {      origin: true,      credentials: securityConfig.cors.credentials    });  }  if (allowedOrigins.includes(requestOrigin)) {    return callback(null, {      origin: true,      credentials: securityConfig.cors.credentials    });  }  console.warn(    JSON.stringify({      level: 'warn',      event: 'CORS_ORIGIN_BLOCKED',      origin: requestOrigin,      method: req.method,      path: req.originalUrl,      ip: req.ip,      requestId: req.headers['x-request-id'] || null,      timestamp: new Date().toISOString()    })  );  return callback(null, {    origin: false  });}function applySecurityMiddleware(app) {  /**   * Trust proxy is useful if API is behind Nginx / load balancer.   */  app.set('trust proxy', 1);  /**   * Secure HTTP headers.   */  app.use(    helmet({      contentSecurityPolicy: false,      crossOriginEmbedderPolicy: false,      referrerPolicy: {        policy: 'no-referrer'      },      frameguard: {        action: 'deny'      },      hsts: {        maxAge: 31536000,        includeSubDomains: true,        preload: true      }    })  );  /**   * CORS restrictions.   */  app.use(    cors({      origin: corsOptionsDelegate,      methods: securityConfig.cors.allowedMethods,      allowedHeaders: securityConfig.cors.allowedHeaders,      exposedHeaders: securityConfig.cors.exposedHeaders,      credentials: securityConfig.cors.credentials,      optionsSuccessStatus: 204    })  );  /**   * Prevent HTTP Parameter Pollution.   */  app.use(hpp());  /**   * Suspicious request logging.   */  app.use(suspiciousRequestLogger);  /**   * SQL injection blocking layer.   */  app.use(sqlInjectionProtection);  /**   * Global rate limit.   */  app.use(standardRateLimiter);}module.exports = {  applySecurityMiddleware};

