'use strict';/** * Blockchain API Middleware * STEP 28 — API Security Controls Integrated */require('dotenv').config();const express = require('express');const securityConfig = require('./config/security.config');const { validateEnvironmentSecrets } = require('./config/env.validator');const { applySecurityMiddleware } = require('./middleware/security.middleware');const app = express();validateEnvironmentSecrets();/** * Request ID middleware. */app.use((req, res, next) => {  const requestId =    req.headers['x-request-id'] ||    `REQ_${Date.now()}_${Math.random().toString(16).slice(2).toUpperCase()}`;  req.requestId = requestId;  res.setHeader('x-request-id', requestId);  next();});/** * STEP 28 — Request size limits. */app.use(  express.json({    limit: securityConfig.requestBodyLimit,    strict: true  }));app.use(  express.urlencoded({    extended: false,    limit: securityConfig.requestBodyLimit  }));/** * STEP 28 — Apply centralized API security controls. */applySecurityMiddleware(app);/** * Routes. */const walletRoutes = require('./routes/wallet.routes');const transactionRoutes = require('./routes/transaction.routes');const fabricRoutes = require('./routes/fabric.routes');app.get('/', (req, res) => {  return res.status(200).json({    success: true,    message: 'Blockchain API Middleware is running',    apiPrefix: '/api/v1',    health: '/api/v1/health',    blockchainStatus: '/api/v1/blockchain/status',    timestamp: new Date().toISOString()  });});app.get('/api/v1/health', (req, res) => {  return res.status(200).json({    success: true,    message: 'Blockchain API Middleware is healthy',    data: {      service: 'Blockchain API Middleware',      version: process.env.npm_package_version || '1.0.0',      environment: process.env.NODE_ENV || 'development',      uptimeSeconds: process.uptime(),      timestamp: new Date().toISOString(),      security: {        helmet: true,        cors: true,        rateLimit: true,        requestSizeLimit: securityConfig.requestBodyLimit,        apiKeyProtection: securityConfig.apiKey.enabled      },      blockchain: {        channelName: process.env.FABRIC_CHANNEL_NAME || null,        chaincodeName: process.env.FABRIC_CHAINCODE_NAME || null,        mspId: process.env.FABRIC_MSP_ID || null      }    },    meta: null,    requestId: req.requestId  });});app.use('/api/v1/wallets', walletRoutes);app.use('/api/v1/transactions', transactionRoutes);app.use('/api/v1/fabric', fabricRoutes);/** * 404 handler. */app.use((req, res) => {  return res.status(404).json({    success: false,    message: 'API endpoint not found',    errorCode: 'ROUTE_NOT_FOUND',    path: req.originalUrl,    requestId: req.requestId || req.headers['x-request-id'] || null  });});/** * Global error handler. */app.use((err, req, res, next) => {  console.error(    JSON.stringify({      level: 'error',      event: 'UNHANDLED_API_ERROR',      message: err.message,      stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,      method: req.method,      path: req.originalUrl,      requestId: req.requestId || req.headers['x-request-id'] || null,      timestamp: new Date().toISOString()    })  );  if (err.type === 'entity.too.large') {    return res.status(413).json({      success: false,      message: 'Request payload is too large',      errorCode: 'REQUEST_PAYLOAD_TOO_LARGE',      requestId: req.requestId || req.headers['x-request-id'] || null    });  }  return res.status(err.status || 500).json({    success: false,    message: 'Internal server error',    errorCode: 'INTERNAL_SERVER_ERROR',    requestId: req.requestId || req.headers['x-request-id'] || null  });});const PORT = Number(process.env.PORT || 3001);const HOST = process.env.HOST || '0.0.0.0';const server = app.listen(PORT, HOST, () => {  console.log(    JSON.stringify({      level: 'info',      event: 'SERVER_STARTED',      service: 'Blockchain API Middleware',      host: HOST,      port: PORT,      environment: process.env.NODE_ENV || 'development',      security: {        helmet: true,        cors: true,        rateLimit: true,        requestSizeLimit: securityConfig.requestBodyLimit,        apiKeyProtection: securityConfig.apiKey.enabled      },      timestamp: new Date().toISOString()    })  );});process.on('unhandledRejection', (reason) => {  console.error(    JSON.stringify({      level: 'error',      event: 'UNHANDLED_REJECTION',      reason: reason instanceof Error ? reason.message : reason,      timestamp: new Date().toISOString()    })  );});process.on('uncaughtException', (error) => {  console.error(    JSON.stringify({      level: 'error',      event: 'UNCAUGHT_EXCEPTION',      message: error.message,      stack: error.stack,      timestamp: new Date().toISOString()    })  );  server.close(() => {    process.exit(1);  });});module.exports = app;

