'use strict';const express = require('express');const { body } = require('express-validator');const fabricController = require('../controllers/fabric.controller');const apiKeyProtection = require('../middleware/apiKey.middleware');const { validateRequest } = require('../middleware/validation.middleware');const router = express.Router();/** * STEP 28 — Fabric route validation */const fabricInvokeValidation = [  body('functionName')    .isString()    .trim()    .isLength({ min: 2, max: 100 })    .matches(/^[A-Za-z0-9_]+$/)    .withMessage('functionName is invalid'),  body('args')    .optional()    .isArray()    .withMessage('args must be an array'),  body('args.*')    .optional()    .custom((value) => {      if (        typeof value !== 'string' &&        typeof value !== 'number' &&        typeof value !== 'boolean'      ) {        throw new Error('Each arg must be string, number, or boolean');      }      return true;    })];/** * Submit Fabric transaction. * API key required because this endpoint directly interacts with Fabric. */router.post(  '/submit',  apiKeyProtection,  fabricInvokeValidation,  validateRequest,  fabricController.submitTransaction);/** * Evaluate Fabric transaction. * API key required because this endpoint can expose chaincode data. */router.post(  '/evaluate',  apiKeyProtection,  fabricInvokeValidation,  validateRequest,  fabricController.evaluateTransaction);module.exports = router;

15. SQL Injection Protection in PostgreSQL Queries
The middleware blocks obvious malicious payloads, but the real protection must be in your DB services.
Use parameterized queries only.
Correct:
const result = await pool.query(  `  SELECT *  FROM blockchain.blockchain_transaction  WHERE wallet_address = $1  ORDER BY created_at DESC  LIMIT $2 OFFSET $3  `,  [walletAddress, limit, offset]);
Wrong:
const result = await pool.query(  `SELECT * FROM blockchain.blockchain_transaction WHERE wallet_address = '${walletAddress}'`);
For dynamic sorting, whitelist the column names:
const allowedSortColumns = {  createdAt: 'created_at',  amount: 'amount',  status: 'status',  transactionType: 'transaction_type'};const sortColumn = allowedSortColumns[sortBy] || 'created_at';const sortDirection = String(sortOrder).toLowerCase() === 'asc' ? 'ASC' : 'DESC';const result = await pool.query(  `  SELECT *  FROM blockchain.blockchain_transaction  ORDER BY ${sortColumn} ${sortDirection}  LIMIT $1 OFFSET $2  `,  [limit, offset]);
This is safe because sortColumn and sortDirection are selected from a whitelist, not directly from user input.

